// Package cep provides client endpoint (CEP) definitions for streaming RPCs
package cep

import (
	"context"

	"github.com/cloudwego/kitex/pkg/streaming"
)

// ClientStreamEndpoint represents a client-side streaming endpoint handler
// It receives a ClientStream and handles the streaming interaction
type ClientStreamEndpoint func(ctx context.Context, stream streaming.ClientStream) error

// ClientStreamMiddleware wraps a ClientStreamEndpoint
type ClientStreamMiddleware func(next ClientStreamEndpoint) ClientStreamEndpoint

// ClientStreamMiddlewareBuilder builds a ClientStreamMiddleware with context
type ClientStreamMiddlewareBuilder func(ctx context.Context) ClientStreamMiddleware

// TypedClientStreamEndpoint is a typed client stream endpoint handler
type TypedClientStreamEndpoint[Req, Resp any] func(ctx context.Context, stream streaming.ClientStreamWrapper[Req, Resp]) error

// ClientStreamChain connects multiple ClientStreamMiddleware into one
func ClientStreamChain(mws ...ClientStreamMiddleware) ClientStreamMiddleware {
	return func(next ClientStreamEndpoint) ClientStreamEndpoint {
		for i := len(mws) - 1; i >= 0; i-- {
			next = mws[i](next)
		}
		return next
	}
}

// DummyClientStreamMiddleware is a no-op middleware
func DummyClientStreamMiddleware(next ClientStreamEndpoint) ClientStreamEndpoint {
	return next
}

// DummyClientStreamEndpoint is a no-op endpoint
func DummyClientStreamEndpoint(ctx context.Context, stream streaming.ClientStream) error {
	return nil
}
