	"github.com/cloudwego/kitex/pkg/streaming"
)

// ServerStreamEndpoint represents a server-side streaming endpoint handler
// It receives a ServerStream and handles the streaming interaction
type ServerStreamEndpoint func(ctx context.Context, stream streaming.ServerStream) error

// ServerStreamMiddleware wraps a ServerStreamEndpoint
type ServerStreamMiddleware func(next ServerStreamEndpoint) ServerStreamEndpoint

// ServerStreamMiddlewareBuilder builds a ServerStreamMiddleware with context
type ServerStreamMiddlewareBuilder func(ctx context.Context) ServerStreamMiddleware

// TypedServerStreamEndpoint is a typed server stream endpoint handler
type TypedServerStreamEndpoint[Req, Resp any] func(ctx context.Context, stream streaming.ServerStreamWrapper[Req, Resp]) error

// ServerStreamChain connects multiple ServerStreamMiddleware into one
func ServerStreamChain(mws ...ServerStreamMiddleware) ServerStreamMiddleware {
	return func(next ServerStreamEndpoint) ServerStreamEndpoint {
		for i := len(mws) - 1; i >= 0; i-- {
			next = mws[i](next)
		}
		return next
	}
}

// DummyServerStreamMiddleware is a no-op middleware
func DummyServerStreamMiddleware(next ServerStreamEndpoint) ServerStreamEndpoint {
	return next
}

// DummyServerStreamEndpoint is a no-op endpoint
func DummyServerStreamEndpoint(ctx context.Context, stream streaming.ServerStream) error {
	return nil
}
